const runs = $input.first().json.workflow_runs || [];
const rows = runs.map(r => ({
  run_id: r.id,
  workflow: r.name,
  status: r.status,
  conclusion: r.conclusion || 'in_progress',
  event: r.event,
  actor: (r.actor && r.actor.login) || 'unknown',
  branch: r.head_branch,
  started_at: r.run_started_at,
  logs_url: r.html_url,
  running: r.status !== 'completed',
  failed: r.conclusion === 'failure' || r.conclusion === 'startup_failure'
}));
const running = rows.filter(r => r.running);
const failed = rows.filter(r => r.failed);
return [{ json: {
  checked_at: new Date().toISOString(),
  total: rows.length,
  running_count: running.length,
  failed_count: failed.length,
  headline: running.length > 0 ? ('RUNNING: ' + running[0].workflow) : (failed.length > 0 ? ('FAILED: ' + failed[0].workflow) : 'idle - all green'),
  runs: rows
} }];

const r = $input.first().json;
const code = r.statusCode || 0;
const body = typeof r.body === 'string' ? r.body : '';
const isWordPress = body.includes('wp-content') || body.includes('wp-includes');
return [{ json: {
  site_url: 'https://oneshot.help/',
  http_status: code,
  reachable: code >= 200 && code < 400,
  looks_like_wordpress: isWordPress,
  checked_at: new Date().toISOString(),
  note: 'Checked from the n8n host on the Mac Studio, not from a public runner.'
} }];
